using System;
using System.Linq;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
public class CPHInline {
  private const string ConfigKey = "portable.wheel.profiles";
  private const string StateKey = "portable.wheel.state";
  private const string ModuleVersion = "2.1.1";
  private string Arg(string key){try{return args.ContainsKey(key)&&args[key]!=null?args[key].ToString().Trim():"";}catch{return "";}}
  private string Read(string key){try{return CPH.GetGlobalVar<string>(key,true)??"";}catch{return "";}}
  private void Broadcast(JObject value){try{CPH.WebsocketBroadcastJson(value.ToString(Formatting.None));}catch{}}
  private long Now(){return DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();}
  private double Clamp(double value,double min,double max,double fallback){if(Double.IsNaN(value)||Double.IsInfinity(value))return fallback;return Math.Max(min,Math.Min(max,value));}
  private string Colour(JToken value,string fallback){string text=(string)value??"";return System.Text.RegularExpressions.Regex.IsMatch(text,"^#[0-9a-fA-F]{6}$")?text.ToLowerInvariant():fallback;}
  private JObject Defaults(){return JObject.Parse(@"{""schemaVersion"":2,""moduleVersion"":""2.1.0"",""activeProfile"":""self-care"",""profiles"":{""self-care"":{""name"":""Self-Care"",""entries"":[{""label"":""Hydrate"",""weight"":3},{""label"":""Stretch"",""weight"":3},{""label"":""Posture check"",""weight"":3},{""label"":""Positive Affirmation"",""weight"":3},{""label"":""Touch Grass"",""weight"":1},{""label"":""Mindfull Breathing"",""weight"":3},{""label"":""Guided Mindfullness"",""weight"":1},{""label"":""Chill Song"",""weight"":2}],""settings"":{""minSpinSeconds"":5,""maxSpinSeconds"":8,""holdSeconds"":4}},""subredeem"":{""name"":""SubRedeem"",""entries"":[{""label"":""Poem"",""weight"":3},{""label"":""Sing Song"",""weight"":1},{""label"":""Short Story"",""weight"":1},{""label"":""Donate charity"",""weight"":2},{""label"":""Sketch"",""weight"":1},{""label"":""Watch video"",""weight"":3},{""label"":""Dealer's Choice"",""weight"":1},{""label"":""Hot pepper"",""weight"":1},{""label"":""Jumping Jacks"",""weight"":2},{""label"":""Try Demo/Play Game"",""weight"":1}],""settings"":{""minSpinSeconds"":5,""maxSpinSeconds"":8,""holdSeconds"":4}}},""position"":{""anchor"":""center"",""offsetX"":0,""offsetY"":0,""sizePercent"":100},""appearance"":{""opacityPercent"":100,""labelSize"":26,""labelColour"":""#ffffff"",""borderColour"":""#ffffff"",""pointerColour"":""#ffffff"",""resultColour"":""#ffffff"",""resultBackground"":""#141414"",""resultOpacityPercent"":82,""palette"":[""#e85d75"",""#f39c35"",""#f3d34a"",""#58b368"",""#3aa7a3"",""#4682d9"",""#8f63d9"",""#d760b8""]}}");}
  private JObject Normalize(JObject input){
    JObject defaults=Defaults(); JObject result=new JObject(); result["schemaVersion"]=2; result["moduleVersion"]=ModuleVersion;
    JObject sourceProfiles=input["profiles"] as JObject??new JObject(); JObject cleanProfiles=new JObject();
    foreach(JProperty property in sourceProfiles.Properties()){
      string slug=System.Text.RegularExpressions.Regex.Replace(property.Name.ToLowerInvariant(),"[^a-z0-9-]",""); if(String.IsNullOrWhiteSpace(slug)||cleanProfiles[slug]!=null)continue;
      JObject source=property.Value as JObject??new JObject(); JArray entries=new JArray();
      foreach(JToken token in source["entries"] as JArray??new JArray()){
        JObject entry=token as JObject; string label=((string)entry?["label"]??"").Trim(); double weight=(double?)entry?["weight"]??0;
        if(!String.IsNullOrWhiteSpace(label))entries.Add(new JObject{{"label",label.Substring(0,Math.Min(100,label.Length))},{"weight",Clamp(weight,0,10000,1)}});
      }
      if(entries.Count==0)continue; JObject settings=source["settings"] as JObject??new JObject(); double min=Clamp((double?)settings["minSpinSeconds"]??5,1,60,5); double max=Clamp((double?)settings["maxSpinSeconds"]??8,1,60,8); if(max<min){double swap=min;min=max;max=swap;}
      cleanProfiles[slug]=new JObject{{"name",((string)source["name"]??slug).Trim()},{"entries",entries},{"settings",new JObject{{"minSpinSeconds",min},{"maxSpinSeconds",max},{"holdSeconds",Clamp((double?)settings["holdSeconds"]??4,0,60,4)}}}};
    }
    if(cleanProfiles.Count==0)cleanProfiles=(JObject)defaults["profiles"].DeepClone(); result["profiles"]=cleanProfiles;
    string active=((string)input["activeProfile"]??"").Trim().ToLowerInvariant(); if(cleanProfiles[active]==null)active=cleanProfiles.Properties().First().Name; result["activeProfile"]=active;
    JObject p=input["position"] as JObject??new JObject(); string anchor=(string)p["anchor"]??"center"; string[] anchors={"top-left","top","top-right","left","center","right","bottom-left","bottom","bottom-right"}; if(!anchors.Contains(anchor))anchor="center";
    result["position"]=new JObject{{"anchor",anchor},{"offsetX",Clamp((double?)p["offsetX"]??0,-50,50,0)},{"offsetY",Clamp((double?)p["offsetY"]??0,-50,50,0)},{"sizePercent",Clamp((double?)p["sizePercent"]??100,20,150,100)}};
    JObject a=input["appearance"] as JObject??new JObject(); JArray palette=new JArray(); foreach(JToken item in a["palette"] as JArray??new JArray())if(palette.Count<12)palette.Add(Colour(item,"#4682d9")); if(palette.Count<2)palette=(JArray)defaults["appearance"]["palette"].DeepClone();
    result["appearance"]=new JObject{{"opacityPercent",Clamp((double?)a["opacityPercent"]??100,10,100,100)},{"labelSize",Clamp((double?)a["labelSize"]??26,12,48,26)},{"labelColour",Colour(a["labelColour"],"#ffffff")},{"borderColour",Colour(a["borderColour"],"#ffffff")},{"pointerColour",Colour(a["pointerColour"],"#ffffff")},{"resultColour",Colour(a["resultColour"],"#ffffff")},{"resultBackground",Colour(a["resultBackground"],"#141414")},{"resultOpacityPercent",Clamp((double?)a["resultOpacityPercent"]??82,0,100,82)},{"palette",palette}};
    return result;
  }
  private JObject Config(){
    string raw=Read(ConfigKey); JObject parsed;
    try{parsed=String.IsNullOrWhiteSpace(raw)?Defaults():JObject.Parse(raw);}catch{parsed=Defaults();}
    if(parsed["schemaVersion"]==null&&parsed["profiles"]!=null){parsed["activeProfile"]="self-care";}
    return Normalize(parsed);
  }
  private void SaveConfig(JObject config){CPH.SetGlobalVar(ConfigKey,config.ToString(Formatting.None),true);}
  private long NextRevision(){try{return ((long?)JObject.Parse(Read(StateKey))["revision"]??0)+1;}catch{return 1;}}
  private JObject IdlePayload(JObject config){string active=(string)config["activeProfile"]; JObject profile=(JObject)config["profiles"][active]; JArray summaries=new JArray();foreach(JProperty item in ((JObject)config["profiles"]).Properties())summaries.Add(new JObject{{"slug",item.Name},{"name",(string)item.Value["name"]??item.Name}});return new JObject{{"moduleVersion",ModuleVersion},{"status","idle"},{"profiles",summaries},{"activeProfile",active},{"activeProfileName",(string)profile["name"]??active},{"entries",profile["entries"].DeepClone()},{"settings",profile["settings"].DeepClone()},{"position",config["position"].DeepClone()},{"appearance",config["appearance"].DeepClone()},{"config",config.DeepClone()},{"currentSpin",JValue.CreateNull()},{"lastResult",JValue.CreateNull()},{"serverTimeMs",Now()}};}
  private void WriteState(JObject payload){JObject envelope=new JObject{{"schemaVersion",1},{"feature","wheel"},{"type","state"},{"revision",NextRevision()},{"payload",payload}};CPH.SetGlobalVar(StateKey,envelope.ToString(Formatting.None),true);Broadcast(envelope);}
  private JObject Spin(string requested,string user,bool wait){JObject config=Config();JObject all=(JObject)config["profiles"];string profile=String.IsNullOrWhiteSpace(requested)?(string)config["activeProfile"]:requested.Trim().ToLowerInvariant();JObject selected=all[profile] as JObject;if(selected==null)throw new Exception("Unknown wheel profile: "+profile);JArray entries=(JArray)selected["entries"];var eligible=new System.Collections.Generic.List<JObject>();double total=0;for(int i=0;i<entries.Count;i++){JObject e=entries[i] as JObject;double w=(double?)e?["weight"]??0;if(w>0){JObject copy=(JObject)e.DeepClone();copy["index"]=i;eligible.Add(copy);total+=w;}}if(eligible.Count==0)throw new Exception("Wheel has no weighted entries.");double pick=new Random(Guid.NewGuid().GetHashCode()).NextDouble()*total;JObject winner=eligible.Last();foreach(JObject e in eligible){pick-=(double)e["weight"];if(pick<=0){winner=e;break;}}JObject settings=(JObject)selected["settings"];double min=(double)settings["minSpinSeconds"],max=(double)settings["maxSpinSeconds"];int duration=(int)Math.Round((min+new Random(Guid.NewGuid().GetHashCode()).NextDouble()*(max-min))*1000);int hold=(int)Math.Round((double)settings["holdSeconds"]*1000);long now=Now();JObject spin=new JObject{{"id",Guid.NewGuid().ToString("N")},{"result",(string)winner["label"]},{"weight",(double)winner["weight"]},{"entryIndex",(int)winner["index"]},{"profile",profile},{"profileName",(string)selected["name"]??profile},{"user",user??""},{"entries",entries.DeepClone()},{"durationMs",duration},{"holdMs",hold},{"rotations",2+Math.Abs(Guid.NewGuid().GetHashCode()%4)},{"startTimeMs",now},{"endTimeMs",now+duration},{"hideTimeMs",now+duration+hold}};config["activeProfile"]=profile;SaveConfig(config);JObject payload=IdlePayload(config);payload["status"]="spinning";payload["currentSpin"]=spin;WriteState(payload);CPH.SetArgument("result",(string)winner["label"]);if(wait)CPH.Wait(duration);return spin;}
  private bool Initialize(){JObject config=Config();SaveConfig(config);WriteState(IdlePayload(config));return true;}
  private bool Configure(){string raw=Arg("config");if(String.IsNullOrWhiteSpace(raw))throw new Exception("Wheel configuration was empty.");JObject config=Normalize(JObject.Parse(raw));SaveConfig(config);WriteState(IdlePayload(config));return true;}
  private bool Clear(){JObject config=Config();JObject payload=IdlePayload(config);try{JObject previous=(JObject)JObject.Parse(Read(StateKey))["payload"];if(previous?["lastResult"]!=null)payload["lastResult"]=previous["lastResult"].DeepClone();}catch{}WriteState(payload);return true;}
  private bool Command(string profile){Spin(profile,Arg("userName"),true);return true;}
  private bool TriggerAdapter(){string user=Arg("userName");if(String.IsNullOrWhiteSpace(user))user=Arg("user");Spin(Arg("profile"),user,true);return true;}
  private bool Health(){JObject config=Config();int count=((JObject)config["profiles"]).Count;if(count<1)throw new Exception("No wheel profiles are configured.");CPH.LogInfo("[Wheel] Health OK: "+count+" profile(s), schema 2, module "+ModuleVersion+".");return true;}
  public bool Execute(){try{string mode=Arg("wheelActionMode").ToLowerInvariant();if(mode=="initialize")return Initialize();if(mode=="configure")return Configure();if(mode=="spin"){Spin(Arg("profile"),Arg("user"),false);return true;}if(mode=="trigger-spin")return TriggerAdapter();if(mode=="clear")return Clear();if(mode=="health")return Health();if(mode=="sub-spin")return Command("subredeem");if(mode=="selfcare-spin")return Command("self-care");throw new Exception("Unknown Wheel mode: "+mode);}catch(Exception ex){CPH.LogError("[Wheel] "+ex.Message);return true;}}
}
